/* Höhenfunktion: identisch mit dem Python-Modell, aus dem die Höhenlinien berechnet wurden (km-Koordinaten, x nach Osten, y nach Süden). */
const logi=(d,w=0.75)=>1/(1+Math.exp(-d/w));
const edge=x=>1.4+(x-4)*0.30;
const noise=(x,y)=>P.NZ.reduce((s,[a,kx,ky,p])=>s+a*Math.sin(kx*x+ky*y+p),0);
const base=(x,y)=>235+(330+9*(10-x)-6*(y-10))*logi(y-edge(x)-1.2)+noise(x,y)*logi(y-edge(x)-0.5,0.8);
function segd(x,y,p,q){const dx=q[0]-p[0],dy=q[1]-p[1];let t=((x-p[0])*dx+(y-p[1])*dy)/(dx*dx+dy*dy);t=Math.max(0,Math.min(1,t));return Math.hypot(x-(p[0]+t*dx),y-(p[1]+t*dy))}
function valley(x,y){let s=0;for(const [pts,dep,w] of P.V){let d=1e9;for(let i=0;i<pts.length-1;i++)d=Math.min(d,segd(x,y,pts[i],pts[i+1]));s+=dep*Math.exp(-((d/w)**2))*logi(y-edge(x)-0.6,0.6)}return s}
function h(x,y){let v=base(x,y);P.G.forEach((g,i)=>{v+=P.amp[i]*Math.exp(-(((x-g[0])/g[2])**2+((y-g[1])/g[3])**2))});v-=valley(x,y);return Math.min(v,1141.2)}
function slope(x,y){const e=0.05;const gx=(h(x+e,y)-h(x-e,y))/(2*e*1000),gy=(h(x,y+e)-h(x,y-e))/(2*e*1000);return Math.hypot(gx,gy)}
