  steine:[
   {t:'Nur beschrieben, nicht erklärt',p:'„Der Weg ist steil“ ist eine Beschreibung. Eine Erklärung sagt, <b>warum</b>: viele Höhenmeter auf kurzer Strecke.',str:'<b>Formulierungshilfen:</b> Unter „Erklären“ stehen Wörter wie <i>weil</i>, <i>deshalb</i>, <i>dadurch</i>.'},
   {t:'Tal und Rücken verwechselt',p:'Beide sehen aus wie ein „V“. Beim Tal zeigt die Spitze bergauf zur Quelle, beim Rücken bergab.',str:'<b>Lupen-Strategie:</b> Blendet die Wege aus und lasst nur Höhenlinien und Gewässer an.'}],
